void FillPanel::set_fill_context(bool value){fill_context_=value;update_color_space_visibility();refresh_channel_visibility();}
void FillPanel::set_enabled_channels(const std::array<bool,15> &values){for(int c=0;c<15;++c){const QSignalBlocker blocker(channel_enabled_[c]);channel_enabled_[c]->setChecked(values[c]);}}
